  padding: 0 !important; }
  #backinstockmodal .form-group,
  #backinstockmodal h1,
  #backinstockmodal p {
    margin: 0;
    padding: 0; }
  #backinstockmodal .bis-form-section {
    padding-top: 115px;
    padding-right: 30px;
    padding-left: 30px; }
    @media (min-width: 769px) {
      #backinstockmodal .bis-form-section {
        padding-right: 70px;
        padding-left: 70px; } }
  #backinstockmodal .modal-content {
    height: calc(100vh - 8px) !important;
    overflow-y: auto !important; }
    @media (min-width: 769px) {
      #backinstockmodal .modal-content {
        height: 75vh !important; } }
  #backinstockmodal .modal-dialog {
    max-width: 430px;
    margin-right: auto;
    margin-left: auto;
    margin-bottom: 0; }
    @media only screen and (max-width: 466px) {
      #backinstockmodal .modal-dialog {
        margin-left: 18px;
        margin-right: 18px; } }
  #backinstockmodal .bis-modal-title {
    color: #262626;
    line-height: 25px;
    font-size: 20px;
